auth.probe_js:
// Medium is a React app that ships its Apollo cache inline, and the viewer sits in it.
// Cookies are the wrong evidence twice over: `sid` is HttpOnly (invisible while a session is live)
// and `uid` outlives sign-out (visible while there is no session) — so document.cookie can be wrong
// in BOTH directions here. Never gate on it.
const st = (() => { try { return window.__APOLLO_STATE__ || window.__PRELOADED_STATE__ || null; } catch (e) { return null; } })();
const fromState = (() => {
  try {
    if (!st) return null;
    const rq = st.ROOT_QUERY || {};
    if (rq.viewer === null) return false;                       // Apollo says it outright: no viewer
    const ref = rq.viewer && (rq.viewer.__ref || rq.viewer.id);
    if (ref && st[ref] && (st[ref].username || st[ref].name)) return st[ref].username || st[ref].name;
    const c = st.client || {};
    if (c.userId) return 'userId:' + c.userId;
    return null;
  } catch (e) { return null; }
})();
if (typeof fromState === 'string') return {signed_in:true, as: fromState};
// Ask Medium's own who-am-I. TRAP: the internal /_/api/* endpoints prepend an XSSI guard
// (`])}while(1);</x>`) to the JSON, so r.json() THROWS on a perfectly good reply. Read it as text
// and cut everything before the first '{'.
try {
  const r = await fetch('/_/api/users/self', {credentials:'include', headers:{accept:'application/json'}});
  if (r.status === 401 || r.status === 403) return {signed_in:false, why:'users/self ' + r.status};
  const t = await r.text();
  const i = t.indexOf('{');
  const j = i < 0 ? null : JSON.parse(t.slice(i));
  const u = (j && j.payload && (j.payload.user || j.payload.value)) || null;
  if (u && (u.username || u.userId)) return {signed_in:true, as: u.username || ('userId:' + u.userId)};
  return {signed_in:false, why:'users/self returned no user'};
} catch (e) {
  if (fromState === false) return {signed_in:false, why:'apollo ROOT_QUERY.viewer is null'};
  const av = document.querySelector('[data-testid="headerAvatar"], [aria-label="user options menu"]');
  return av ? {signed_in:true, why:'WEAK: header avatar present, no viewer state and users/self failed'}
            : {signed_in:false, why:'no viewer state, no avatar, users/self failed: ' + e.message};
}
